module file_deletion(\n    input clk,\n    input rst_n,\n    input start,\n    input [13:0] nr,\n    input [13:0] nc,\n    input [2:0] N,\n    input [231:0] points_packed,\n    output reg [3:0] moves,\n    output reg done\n);\n    \n    // State definitions\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] LOAD = 3'd1;\n    localparam [2:0] SORT = 3'd2;\n    localparam [2:0] ITERATE = 3'd3;\n    localparam [2:0] COMPUTE = 3'd4;\n    localparam [2:0] FINISH = 3'd5;\n    \n    // Internal registers\n    reg [2:0] state, next_state;\n    reg [2:0] count;\n    reg [3:0] max_f;\n    reg [3:0] current_f;\n    reg [3:0] n_delete;\n    \n    // Unpacked points storage\n    reg [13:0] x_coords [0:7];\n    reg [13:0] y_coords [0:7];\n    reg types [0:7];\n    \n    // Compressed coordinates\n    reg [13:0] xs [0:9];\n    reg [13:0] ys [0:9];\n    reg [3:0] xs_count;\n    reg [3:0] ys_count;\n    \n    // Rectangle boundaries\n    reg [3:0] x_left_idx, x_right_idx;\n    reg [3:0] y_low_idx, y_high_idx;\n    \n    // Loop counters\n    reg [3:0] i, j;\n    \n    // Unpack points\n    wire [28:0] point_wire [0:7];\n    generate\n        genvar k;\n        for (k = 0; k < 8; k = k + 1) begin : unpack\n            assign point_wire[k] = points_packed[29*k +: 29];\n        end\n    endgenerate\n    \n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) state <= IDLE;\n        else state <= next_state;\n    end\n    \n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: if (start) next_state = LOAD;\n            LOAD: next_state = SORT;\n            SORT: if (count >= 4'd9) next_state = ITERATE;\n            ITERATE: next_state = COMPUTE;\n            COMPUTE: if (i >= N) next_state = FINISH;\n            FINISH: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n    \n    // Main processing\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            moves <= 4'd0;\n            done <= 1'b0;\n            max_f <= 4'd0;\n            count <= 3'd0;\n            xs_count <= 4'd0;\n            ys_count <= 4'd0;\n            n_delete <= 4'd0;\n            x_left_idx <= 4'd0;\n            x_right_idx <= 4'd0;\n            y_low_idx <= 4'd0;\n            y_high_idx <= 4'd0;\n            i <= 4'd0;\n            j <= 4'd0;\n            current_f <= 4'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        max_f <= 4'd0;\n                        count <= 3'd0;\n                        i <= 4'd0;\n                        n_delete <= 4'd0;\n                    end\n                end\n                \n                LOAD: begin\n                    // Unpack points and count deletes\n                    for (integer idx = 0; idx < 8; idx = idx + 1) begin\n                        if (idx < N) begin\n                            types[idx] <= point_wire[idx][28];\n                            x_coords[idx] <= point_wire[idx][27:14];\n                            y_coords[idx] <= point_wire[idx][13:0];\n                            if (point_wire[idx][28]) n_delete <= n_delete + 1;\n                        end\n                    end\n                    // Add screen boundaries\n                    xs[0] <= 14'd0;\n                    xs[1] <= nr;\n                    ys[0] <= 14'd0;\n                    ys[1] <= nc;\n                    xs_count <= 4'd2;\n                    ys_count <= 4'd2;\n                end\n                \n                SORT: begin\n                    // Add unique coordinates\n                    if (count < N) begin\n                        // Add x coordinate if not boundary\n                        if (x_coords[count] != 14'd0 && x_coords[count] != nr) begin\n                            xs[xs_count] <= x_coords[count];\n                            xs_count <= xs_count + 1;\n                        end\n                        // Add y coordinate if not boundary\n                        if (y_coords[count] != 14'd0 && y_coords[count] != nc) begin\n                            ys[ys_count] <= y_coords[count];\n                            ys_count <= ys_count + 1;\n                        end\n                        count <= count + 1;\n                    end else begin\n                        // Reset for iteration\n                        count <= 3'd0;\n                        x_left_idx <= 4'd0;\n                        x_right_idx <= 4'd1;\n                        y_low_idx <= 4'd0;\n                        y_high_idx <= 4'd1;\n                    end\n                end\n                \n                ITERATE: begin\n                    // Iterate over rectangle boundaries\n                    if (x_left_idx < xs_count - 1) begin\n                        if (x_right_idx < xs_count) begin\n                            if (y_low_idx < ys_count - 1) begin\n                                if (y_high_idx < ys_count) begin\n                                    current_f <= 4'd0;\n                                    i <= 4'd0;\n                                    next_state = COMPUTE;\n                                end else begin\n                                    y_high_idx <= y_low_idx + 1;\n                                    y_low_idx <= y_low_idx + 1;\n                                end\n                            end else begin\n                                y_low_idx <= 4'd0;\n                                y_high_idx <= 4'd1;\n                                x_right_idx <= x_right_idx + 1;\n                            end\n                        end else begin\n                            x_right_idx <= x_left_idx + 1;\n                            x_left_idx <= x_left_idx + 1;\n                        end\n                    end else begin\n                        next_state = FINISH;\n                    end\n                end\n                \n                COMPUTE: begin\n                    // Check if point is inside current rectangle\n                    if (i < N) begin\n                        if (x_coords[i] >= xs[x_left_idx] && x_coords[i] <= xs[x_right_idx] &&\n                            y_coords[i] >= ys[y_low_idx] && y_coords[i] <= ys[y_high_idx]) begin\n                            if (types[i]) current_f <= current_f + 1;\n                            else current_f <= current_f - 1;\n                        end\n                        i <= i + 1;\n                    end else begin\n                        if (current_f > max_f) max_f <= current_f;\n                        next_state = ITERATE;\n                    end\n                end\n                \n                FINISH: begin\n                    moves <= n_delete - max_f;\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\nendmodule